//! Native TEXTAREA textLength reports the normalized API value in UTF-16 units.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form><textarea id=area name=q wrap=hard cols=1>A\r\n😀Z</textarea><input id=neighbor value=seed></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://textarea-text-length.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn textarea_text_length_canonical_readonly_accessor_and_initial_normalized_units(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'textLength');if(!a||!a.enumerable||!a.configurable||typeof a.get!=='function'||a.set!==undefined||a.get.name!=='get textLength'||a.get.length!==0||Object.hasOwn(x,'textLength'))throw 'canonical readonly text length';if(x.value!=='A\\n😀Z'||x.textLength!==5||x.textLength!==x.value.length)throw 'initial normalized UTF16 length';");}
#[test]
fn textarea_text_length_follows_dirty_api_value_not_default_or_submission_wrapping(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),events=0;x.oninput=function(){events++;};x.onchange=function(){events++;};x.value='😀\\r\\nB';x.cols=1;if(x.textLength!==4||x.value!=='😀\\nB'||x.defaultValue!=='A\\n😀Z'||events)throw 'live normalized value length';x.value=null;if(x.textLength!==0||x.value!==''||x.defaultValue!=='A\\n😀Z'||events)throw 'null empty API value';");}
#[test]
fn textarea_text_length_native_reset_uses_admitted_default(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.value='😀\\r\\nR';if(x.textLength!==4||x.defaultValue!=='A\\n😀Z')throw 'dirty API length distinct from default';");let node=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();let owner=f.controls[&node].owner.unwrap();let nodes=format!("{:?}",d.nodes);assert!(f.prepare_text_default(node,Some("unsupported new default")).is_err());assert_eq!(format!("{:?}",d.nodes),nodes);f.reset_in_document(&d,owner).unwrap();p.begin_job();run(&mut d,&mut f,&mut p,"if(x.textLength!==5||x.value!=='A\\n😀Z'||x.defaultValue!=='A\\n😀Z')throw 'reset admitted normalized length';");assert!(!f.controls[&node].dirty_value);}
#[test]
fn textarea_text_length_assignment_keeps_real_value_and_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,childList:true,subtree:true,characterData:true});x.textLength={valueOf:function(){throw 'no conversion';}};if(x.textLength!==5||x.value!=='A\\n😀Z'||watch.takeRecords().length||Object.hasOwn(x,'textLength'))throw 'readonly length assignment';var caught=false;try{(function(){'use strict';x.textLength=1;})();}catch(e){caught=e instanceof TypeError;}if(!caught||x.textLength!==5)throw 'strict readonly length';");}

#[test]
fn textarea_text_length_concrete_brand_saved_authority_and_explicit_inert_refusal(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),C=HTMLTextAreaElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'textLength');for(var bad of [{},Object.create(P),document.body,document.createElement('input'),document.createElement('select'),document.createElementNS('urn:foreign','textarea'),new Document().createElementNS('http://www.w3.org/1999/xhtml','TEXTAREA')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'length concrete brand';}var inert=new Document().createElementNS('http://www.w3.org/1999/xhtml','p:textarea');for(var operation of [function(){return a.get.call(inert);},function(){return inert.textLength;}]){var caught=false;try{operation();}catch(e){caught=e.name==='NotSupportedError'&&e.message.indexOf('admitted native value state')!==-1;}if(!caught)throw 'unsupported value state explicit';}Object.defineProperty(x,'textLength',{value:'author',writable:true,configurable:true});if(x.textLength!=='author'||a.get.call(x)!==5)throw 'saved native authority';delete x.textLength;delete window.HTMLTextAreaElement;if(x.textLength!==5||Object.getPrototypeOf(x)!==P||!(x instanceof C))throw 'saved canonical length';"#);}
#[test]
fn textarea_text_length_native_copy_detach_and_reconnect_keep_actual_value(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.value='😀\\r\\nQ';var copy=x.cloneNode(true);if(copy.textLength!==4||copy.value!==x.value||copy.defaultValue!==x.defaultValue)throw 'native dirty copy length';x.remove();if(x.textLength!==4||x.value!=='😀\\nQ')throw 'detached actual native length';document.body.appendChild(x);copy.value='Z';if(x.textLength!==4||copy.textLength!==1||x.value!=='😀\\nQ')throw 'independent native length';");}
#[test]
fn textarea_text_length_reads_preserve_dirty_editor_defaults_cursors_flags_and_events(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),events=0;x.oninput=function(){events++;};x.onchange=function(){events++;};x.value='😀\\r\\nQ';x.readOnly=true;x.required=true;x.disabled=true;var old=x.firstChild,watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,childList:true,subtree:true,characterData:true});");let node=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let c=f.controls.get_mut(&node).unwrap();c.value.cursor=2;c.value.anchor=1;c.value.offset=1;}let capture=|f:&Forms|{let c=&f.controls[&node];(c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.name.clone(),c.disabled,c.readonly,c.required,c.dirty_value)};let before=capture(&f);let commits=p.state.dom_commits;let nodes=format!("{:?}",d.nodes);for _ in 0..4{p.begin_job();run(&mut d,&mut f,&mut p,"if(x.textLength!==4||x.value.length!==4||x.firstChild!==old||x.defaultValue!=='A\\n😀Z'||events||watch.takeRecords().length)throw 'length read is observational';");assert_eq!(capture(&f),before);assert_eq!(p.state.dom_commits,commits);assert_eq!(format!("{:?}",d.nodes),nodes);}}
#[test]
fn textarea_text_length_counts_full_native_utf16_bound_without_string_allocation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('area');x.value='{}';","😀".repeat(2048)));let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("native textarea")};let before=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let strings=p.state.limits.host.string_bytes;let retained=p.state.retained_limit;p.begin_job();p.state.copy_work=0;p.state.retained_limit=p.state.retained;p.state.limits.host.string_bytes=0;assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.textarea_text_length_get(object),Ok(Value::Number(4096.0))));assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),before);p.state.limits.host.string_bytes=strings;p.state.retained_limit=retained;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.textLength!==4096||x.value.length!==4096)throw 'full native UTF16 limit';");}
#[test]
fn textarea_text_length_work_deadline_refusal_is_observational_and_recovers(){for mode in 0..3{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('area'),watch=new MutationObserver(function(){{}});watch.observe(x,{{attributes:true,childList:true,subtree:true,characterData:true}});x.value='{}';","😀".repeat(128)));let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("native textarea")};let nodes=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let native=f.controls.iter().map(|(n,c)|(*n,c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value)).collect::<Vec<_>>();p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.host_work=16,_=>p.state.execution_deadline=Some(Instant::now())};assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.textarea_text_length_get(object).is_err());assert_eq!(format!("{:?}",d.nodes),nodes);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value)).collect::<Vec<_>>(),native);p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.textLength!==256||watch.takeRecords().length)throw 'fresh observational length recovery';");}}
#[test]
fn textarea_text_length_saved_child_origin_refuses_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var get=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLTextAreaElement.prototype,'textLength').get;if(get.call(x)!==5)throw 'same origin length';");p.set_location(&crate::navigation::address("https://foreign-textarea-text-length.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute("get.call(x);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.set_location(&crate::navigation::address("https://textarea-text-length.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(get.call(x)!==5||x.textLength!==5)throw 'fresh origin length recovery';");}
